dev-browser --headless --timeout 15 <<'EOF'
const page = await browser.getPage("crash");
await page.goto("http://127.0.0.1:4175/index.html");
const errors = [];
page.on("console", msg => { if (msg.type() === "error") errors.push(msg.text()); });
page.on("pageerror", err => errors.push(String(err)));
await page.click("#soundToggle");
const on = await page.evaluate(() => ({ label: document.querySelector("#soundLabel").textContent, pressed: document.querySelector("#soundToggle").getAttribute("aria-pressed") }));
await page.click("#soundToggle");
const off = await page.evaluate(() => ({ label: document.querySelector("#soundLabel").textContent, pressed: document.querySelector("#soundToggle").getAttribute("aria-pressed") }));
console.log(JSON.stringify({ on, off, errors }, null, 2));
EOF
